public class EmployeeSortTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String sorted(Employee... employees) {
        java.util.List<Employee> list = new java.util.ArrayList<>(java.util.Arrays.asList(employees));
        try {
            EmployeeSort.sort(list);
            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < list.size(); i++) {
                Employee e = list.get(i);
                if (i > 0) sb.append(", ");
                sb.append(e.dept()).append(" ").append(e.name()).append(" ").append(e.salary());
            }
            return sb.append("]").toString();
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("dept ascending first",
                "[HR Amy 60000, IT Ann 70000, IT Bob 50000]",
                sorted(new Employee("IT", "Bob", 50000),
                       new Employee("HR", "Amy", 60000),
                       new Employee("IT", "Ann", 70000)));
        check("salary DESCENDING within one dept",
                "[Ops Cara 90000, Ops Drew 80000, Ops Ella 70000]",
                sorted(new Employee("Ops", "Ella", 70000),
                       new Employee("Ops", "Cara", 90000),
                       new Employee("Ops", "Drew", 80000)));
        check("name breaks salary ties",
                "[QA Abe 55000, QA Zoe 55000]",
                sorted(new Employee("QA", "Zoe", 55000),
                       new Employee("QA", "Abe", 55000)));
        check("all three levels together",
                "[HR Gil 40000, HR Ann 30000, HR Bea 30000, IT Hal 40000]",
                sorted(new Employee("IT", "Hal", 40000),
                       new Employee("HR", "Bea", 30000),
                       new Employee("HR", "Gil", 40000),
                       new Employee("HR", "Ann", 30000)));
        check("single employee", "[HR Solo 10000]",
                sorted(new Employee("HR", "Solo", 10000)));
        check("empty list is fine", "[]", sorted());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

