record Employee(String dept, String name, int salary) { }

public class EmployeeSort {

    public static void sort(java.util.List<Employee> list) {
        list.sort(java.util.Comparator.comparing(Employee::dept)
                .thenComparing(java.util.Comparator.comparingInt(Employee::salary).reversed())
                .thenComparing(Employee::name));
    }
}
